use serde_json::{json, Value};

use crate::agent_tools::common::http_client;
use crate::agent_tools::{PermissionClass, Tool, ToolContext, ToolStatus, err, ok};

#[derive(Debug)]
pub struct WebExtract;

#[async_trait::async_trait]
impl Tool for WebExtract {
    fn name(&self) -> &'static str {
        "web_extract"
    }
    fn icon(&self) -> &'static str {
        ""
    }
    fn call_summary(&self, args: &Value) -> String {
        args["url"].as_str().unwrap_or_default().to_string()
    }
    fn schema(&self) -> Value {
        json!({
            "type": "function",
            "function": {
                "name": self.name(),
                "description": indoc::indoc! {"
                    Fetch the full readable content of a specific URL via Tavily.
                    Use when a URL is known and its full content is needed (docs,
                    READMEs, changelogs). More thorough than web_search snippets.
                "},
                "parameters": {
                    "type": "object",
                    "properties": {
                        "url": { "type": "string", "description": "The URL to extract content from." }
                    },
                    "required": ["url"]
                }
            }
        })
    }
    fn permission(&self) -> PermissionClass {
        PermissionClass::ReadOnly
    }
    fn permission_prompt(&self, _args: &Value) -> (String, String) {
        (String::new(), String::new())
    }
    fn availability(&self) -> Result<(), String> {
        std::env::var("TAVILY_API_KEY")
            .map(|_| ())
            .map_err(|_| "TAVILY_API_KEY not found".to_string())
    }
    async fn execute(&self, ctx: &ToolContext, args: Value) -> (ToolStatus, Value) {
        let url = match args["url"].as_str() {
            Some(u) => u,
            None => return err("url argument not found"),
        };

        let api_key = match std::env::var("TAVILY_API_KEY") {
            Ok(key) => key,
            Err(_) => return err("TAVILY_API_KEY not set in environment"),
        };

        let client = http_client();
        let response = match client
            .post("https://api.tavily.com/extract")
            .header("Content-Type", "application/json")
            .header("Authorization", format!("Bearer {api_key}"))
            .json(&json!({ "urls": [url] }))
            .send()
            .await
        {
            Ok(res) => res,
            Err(e) => return err(format!("Request failed: {e}")),
        };

        let result: Value = match response.json().await {
            Ok(j) => j,
            Err(e) => return err(format!("Failed to parse response: {e}")),
        };

        if let Some(msg) = result["message"].as_str() {
            return err(msg.to_string());
        }

        // Mirror the extracted text to the TUI for parity with web_search.
        if let Some(results) = result["results"].as_array() {
            let mut text = String::new();
            for r in results {
                if let Some(content) = r["raw_content"].as_str() {
                    text.push_str(content);
                    text.push('\n');
                }
            }
            ctx.handle.tool_output(&text, "");
        }

        ok(json!({
            "status": "success",
            "url": url,
            "content": result,
        }))
    }
}